-- NUVEM (escrito à mão, depois do drizzle-kit): a forma do nome que o SQL usa
-- como RECORTE na procura de cadastros parecidos (`servicos/duplicados.ts`).
-- Quem decide é o JS (`textos.chave_busca`); aqui só se tira acento e caixa
-- para o recorte não deixar ninguém de fora. A lista de acentos é mais larga
-- que a de `csso_sem_acento_maiusculo` (ñ, ý, å, ø, ł, ș…), que fica como está
-- porque o código curto do treinamento depende dela.
CREATE OR REPLACE FUNCTION csso_nome_chave(p text) RETURNS text
LANGUAGE sql IMMUTABLE AS $$
  SELECT translate(lower(coalesce(p, '')),
    'áàâãäåāăąéèêëēĕėęěíìîïĩīĭįıóòôõöøōŏőúùûüũūŭůűųçćĉċčñńņňýÿŷźżžśŝşšșğĝġģđďłľĺļŕřţťț',
    'aaaaaaaaaeeeeeeeeeiiiiiiiiiooooooooouuuuuuuuuucccccnnnnyyyzzzsssssggggddllllrrttt')
$$;
